-- Additive, anonymous helpful-vote storage for published reviews.
-- The voter hash is generated by the server; raw visitor identifiers are not stored.
BEGIN;
CREATE TABLE IF NOT EXISTS public.review_helpful_votes (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  review_id BIGINT NOT NULL REFERENCES public.approved_reviews(id) ON DELETE CASCADE,
  voter_hash CHAR(64) NOT NULL,
  is_helpful BOOLEAN NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT review_helpful_votes_one_per_voter UNIQUE (review_id, voter_hash)
);
CREATE INDEX IF NOT EXISTS idx_review_helpful_votes_review
  ON public.review_helpful_votes(review_id, is_helpful);
COMMIT;
